/**
 * OrthographicPhysicsCamera - Base class for orthographic physics-integrated cameras
 *
 * Extends THREE.OrthographicCamera to add physics worker synchronization.
 * Use directly with renderer.render(scene, camera).
 *
 * The camera uses a `zoom` property (in world units) to define the visible area.
 * This is more intuitive than setting left/right/top/bottom directly.
 *
 * **Usage**
 *
 * ```js
 * // Subclass to create specific camera types
 * class My2DCamera extends OrthographicPhysicsCamera {
 *   update(delta) {
 *     this._ensureActive();
 *     // Update camera position
 *     this._syncToSharedCamera();
 *   }
 * }
 * ```
 *
 * @class OrthographicPhysicsCamera
 * @extends THREE.OrthographicCamera
 * @short Base orthographic camera for 2D physics games.
 * @category Camera
 * @tags Physics, Camera, 2D, Orthographic, WebGPU, WebGL
 */
export class OrthographicPhysicsCamera {
    /**
     * Create an OrthographicPhysicsCamera.
     *
     * @param {Object} physics - Physics instance
     * @param {Object} [options={}] - Camera options
     * @param {number} [options.zoom=10] - Visible area half-height in world units
     * @param {number} [options.near=0.1] - Near clipping plane
     * @param {number} [options.far=1000] - Far clipping plane
     * @param {THREE.Object3D} [options.target=null] - Target object to follow
     * @param {number} [options.playerBodyIndex] - Explicit body index to follow
     */
    constructor(physics: any, options?: {
        zoom?: number;
        near?: number;
        far?: number;
        target?: THREE.Object3D;
        playerBodyIndex?: number;
    });
    /**
     * Reference to Physics instance.
     * @type {Object}
     */
    physics: any;
    /**
     * Target object the camera follows.
     * @type {THREE.Object3D|null}
     */
    target: THREE.Object3D | null;
    /**
     * Internal reference to shared camera buffer.
     * @type {Object}
     * @private
     */
    private _sharedCamera;
    /**
     * Internal reference to shared physics state for timing.
     * @type {Object}
     * @private
     */
    private _sharedPhysic;
    /**
     * Whether the camera has been disposed.
     * @type {boolean}
     * @private
     */
    private _disposed;
    /**
     * Explicit player body index (overrides auto-detection from target).
     * @type {number|undefined}
     * @private
     */
    private _explicitPlayerBodyIndex;
    /**
     * Zoom level (visible area half-height in world units).
     * @type {number}
     * @private
     */
    private _zoom;
    /**
     * Set the zoom level (visible area half-height in world units).
     * Automatically updates the frustum and projection matrix.
     * @type {number}
     */
    set orthoZoom(value: number);
    /**
     * Get the zoom level (visible area half-height in world units).
     * @type {number}
     */
    get orthoZoom(): number;
    left: number;
    right: any;
    top: number;
    bottom: number;
    /**
     * Sync playerBodyIndex to shared camera buffer.
     * Priority: explicit option > target mesh userData > unchanged
     * @private
     */
    private _syncPlayerBodyIndex;
    /**
     * Update camera state. Must be called each frame.
     * Implement in subclass.
     *
     * @abstract
     * @param {number} delta - Time delta in seconds
     */
    update(delta: number): void;
    /**
     * Ensure this camera is the active one.
     * If not already active, sets this as the active camera and re-initializes physics mode.
     * Subclasses should call this at the start of their update() method.
     *
     * @protected
     */
    protected _ensureActive(): void;
    /**
     * Called when this camera becomes the active camera.
     * Override in subclasses to handle activation logic.
     *
     * @protected
     */
    protected _onActivate(): void;
    /**
     * Called when this camera is no longer the active camera.
     * Override in subclasses to handle deactivation logic.
     *
     * @protected
     */
    protected _onDeactivate(): void;
    /**
     * Initialize physics mode for this camera type.
     * Override in subclass to set appropriate shared camera flags.
     *
     * @abstract
     * @protected
     */
    protected _initPhysicsMode(): void;
    /**
     * Set the target object the camera follows.
     * Automatically syncs playerBodyIndex if target has a dynamic physics body.
     *
     * @param {THREE.Object3D} target - Object to follow
     * @returns {this} For chaining
     */
    setTarget(target: THREE.Object3D): this;
    /**
     * Get interpolation alpha from Physics class (frame-cached).
     * Delegating to Physics ensures all consumers get identical alpha values
     * within the same frame, preventing timing mismatches.
     *
     * @returns {number} Interpolation factor (0-1)
     * @protected
     */
    protected _getInterpolationAlpha(): number;
    /**
     * Sync camera position and rotation from physics worker.
     * Uses interpolation between previous and current physics state.
     *
     * @protected
     */
    protected _syncFromWorker(): void;
    /**
     * Write camera position/quaternion to shared camera buffer.
     * Use this when camera controls its own position (usingStaticCamera=1).
     *
     * @protected
     */
    protected _syncToSharedCamera(): void;
    /**
     * Get position of a target object for camera following.
     * Uses mesh.position directly since body.sync() must be called before camera.update().
     *
     * @param {THREE.Object3D} target - Target object to follow
     * @param {THREE.Vector3} out - Vector to store the position
     * @returns {THREE.Vector3} The output vector with target position
     * @protected
     */
    protected _getInterpolatedTargetPosition(target: THREE.Object3D, out: THREE.Vector3): THREE.Vector3;
    /**
     * Sync projection parameters to sharedCamera.
     * For orthographic cameras, fov=0 signals ortho mode to the worker.
     *
     * @protected
     */
    protected _syncProjection(): void;
    /**
     * Handle window resize. Updates frustum and projection matrix.
     *
     * @param {number} [width=window.innerWidth] - New width
     * @param {number} [height=window.innerHeight] - New height
     * @returns {this} For chaining
     */
    resize(width?: number, height?: number): this;
    /**
     * Clean up resources and event listeners.
     * Call when camera is no longer needed.
     */
    dispose(): void;
}
